<?php
require __DIR__.'/includes/bootstrap.php';require_role('admin');$page_title='Управление пользователями';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['user_id']??0);$role=(string)($_POST['role']??'user');$allowed=['user','inspector','officer','admin'];if(!in_array($role,$allowed,true))$errors[]='Неизвестная роль.';elseif($id===(int)current_user()['id'] && $role!=='admin')$errors[]='Нельзя снять роль администратора с текущего аккаунта.';else{$s=$pdo->prepare('UPDATE users SET role=? WHERE id=?');$s->execute([$role,$id]);if($s->rowCount()===0){$s=$pdo->prepare('SELECT id FROM users WHERE id=?');$s->execute([$id]);if(!$s->fetch())$errors[]='Пользователь не найден.';}if(!$errors)set_flash('success','Роль пользователя обновлена.');}}
$users=$pdo->query('SELECT id,full_name,email,role,created_at,last_login_at FROM users ORDER BY created_at DESC LIMIT 500')->fetchAll();include __DIR__.'/includes/header.php';
?>
<section class="page-intro"><span class="eyebrow">Администрирование</span><h1>Пользователи и роли</h1><p>Назначайте служебные права. Пользовательская регистрация не позволяет самостоятельно получить роль сотрудника.</p></section><?php foreach($errors as $err): ?><div class="alert alert-danger"><?= e($err) ?></div><?php endforeach; ?>
<section class="panel"><div class="panel-header"><h2>Учётные записи</h2><p>Всего пользователей: <?= count($users) ?></p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Пользователь</th><th>Зарегистрирован</th><th>Последний вход</th><th>Роль и права</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['full_name']) ?></strong><br><span class="muted tiny"><?= e($u['email']) ?></span></td><td><?= e(date('d.m.Y',strtotime($u['created_at']))) ?></td><td><?= $u['last_login_at']?e(date('d.m.Y H:i',strtotime($u['last_login_at']))):'—' ?></td><td><form method="post" style="display:flex;gap:8px;align-items:center"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><select class="input" name="role" style="min-width:165px;padding:8px" aria-label="Роль пользователя"><?php foreach(['user'=>'Владелец','inspector'=>'Инспектор','officer'=>'Сотрудник ГИБДД','admin'=>'Администратор'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $u['role']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button type="submit" class="btn btn-ghost btn-small">Сохранить</button></form></td><td><?php if((int)$u['id']===(int)current_user()['id']): ?><span class="badge badge-blue">Вы</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel panel-pad" style="margin-top:18px"><h2>Что даёт каждая роль</h2><div class="summary-row"><span>Владелец</span><strong>Поиск, карточки авто, собственные штрафы и кабинет</strong></div><div class="summary-row"><span>Инспектор</span><strong>Служебный просмотр реестра и штрафов</strong></div><div class="summary-row"><span>Сотрудник ГИБДД</span><strong>Регистрация ТС, фото и оформление штрафов</strong></div><div class="summary-row"><span>Администратор</span><strong>Все возможности + управление ролями</strong></div></section>
